3	// Scope represents a single block's variable type environment
4	type Scope struct {
5		vars   map[string]TypeInfo
6		parent *Scope
7	}
8	
9	func newScope(parent *Scope) *Scope {
10		return &Scope{
11			vars:   make(map[string]TypeInfo),
12			parent: parent,
13		}
14	}
15	
16	// Define adds a variable to this scope
17	func (s *Scope) define(name string, t TypeInfo) {
18		s.vars[name] = t
19	}
20	
21	// Lookup searches for a variable type in this scope and parent scopes
22	func (s *Scope) lookup(name string) (TypeInfo, bool) {
23		if t, exists := s.vars[name]; exists {
24			return t, true
25		}
26		if s.parent != nil {
27			return s.parent.lookup(name)
28		}
29		return UnknownType, false
30	}
31	
32	// FuncDef represents a function signature
33	type FuncDef struct {
34		Name       string
35		ParamTypes []TypeInfo // parameter types in order
36		ReturnType TypeInfo   // return type
37	}
38	
39	// StructDef represents a struct definition
40	type StructDef struct {
41		Name   string
42		Fields map[string]TypeInfo // fieldname -> type
43	}
44	
45	// TypeEnv is the complete type environment
46	type TypeEnv struct {
47		current   *Scope
48		structs   map[string]StructDef
49		functions map[string]FuncDef
50	}
51	
52	// NewTypeEnv creates a new type environment
53	func NewTypeEnv() *TypeEnv {
54		global := newScope(nil)
55		return &TypeEnv{
56			current:   global,
57			structs:   make(map[string]StructDef),
58			functions: make(map[string]FuncDef),
59		}
60	}
61	
62	// EnterScope creates a new nested scope
63	func (e *TypeEnv) EnterScope() {
64		e.current = newScope(e.current)
65	}
66	
67	// ExitScope pops to parent scope
68	func (e *TypeEnv) ExitScope() {
69		if e.current.parent != nil {
70			e.current = e.current.parent
71		}
72	}
73	
74	// Define adds a variable to current scope
75	func (e *TypeEnv) Define(name string, t TypeInfo) {
76		e.current.define(name, t)
77	}
78	
79	// Lookup searches for a variable in current scope and parents
80	func (e *TypeEnv) Lookup(name string) (TypeInfo, bool) {
81		return e.current.lookup(name)
82	}
83	
84	// RegisterStruct adds a struct definition
85	func (e *TypeEnv) RegisterStruct(name string, def StructDef) {
86		e.structs[name] = def
87	}
88	
89	// LookupStruct finds a struct definition
90	func (e *TypeEnv) LookupStruct(name string) (StructDef, bool) {
91		s, exists := e.structs[name]
92		return s, exists
93	}
94	
95	// RegisterFunc adds a function signature
96	func (e *TypeEnv) RegisterFunc(name string, def FuncDef) {
97		e.functions[name] = def
98	}
99	
100	// LookupFunc finds a function signature
101	func (e *TypeEnv) LookupFunc(name string) (FuncDef, bool) {
102		f, exists := e.functions[name]
103		return f, exists
104	}
