3	import (
4		"fmt"
5	
6		"github.com/user/freelang-evolving-compiler/internal/ast"
7	)
8	
9	// TypeError represents a type checking error
10	type TypeError struct {
11		Message string
12		Line    int
13		Col     int
14	}
15	
16	// TypeChecker validates types in an AST
17	type TypeChecker struct {
18		env      *TypeEnv
19		errors   []TypeError
20		hardMode bool // if true, type errors are fatal
21	}
22	
23	// NewTypeChecker creates a new type checker in soft mode
24	func NewTypeChecker() *TypeChecker {
25		return &TypeChecker{
26			env:      NewTypeEnv(),
27			errors:   []TypeError{},
28			hardMode: false,
29		}
30	}
31	
32	// NewTypeCheckerHard creates a new type checker in hard mode
33	func NewTypeCheckerHard() *TypeChecker {
34		return &TypeChecker{
35			env:      NewTypeEnv(),
36			errors:   []TypeError{},
37			hardMode: true,
38		}
39	}
40	
41	// Check walks the AST and validates types, returning any errors found
42	func (tc *TypeChecker) Check(root *ast.Node) []TypeError {
43		if root != nil {
44			tc.checkNode(root)
45		}
46		return tc.errors
47	}
48	
49	// checkNode recursively checks a node and returns its inferred type
50	func (tc *TypeChecker) checkNode(n *ast.Node) TypeInfo {
51		if n == nil {
52			return UnknownType
53		}
54	
55		switch n.Kind {
56		case ast.NodeProgram:
57			// Check all top-level statements
58			for _, child := range n.Children {
59				tc.checkNode(child)
60			}
61			return UnitType
62	
63		case ast.NodeStructDecl:
64			return tc.checkStructDecl(n)
65	
66		case ast.NodeLetDecl:
67			return tc.checkLetDecl(n)
68	
69		case ast.NodeFnDecl:
70			return tc.checkFnDecl(n)
71	
72		case ast.NodeBlockStmt:
73			tc.env.EnterScope()
74			for _, child := range n.Children {
75				tc.checkNode(child)
76			}
77			tc.env.ExitScope()
78			return UnitType
79	
80		case ast.NodeIfStmt:
81			if len(n.Children) > 0 {
82				condType := tc.checkNode(n.Children[0])
83				if condType.Kind != TypeBool && condType.Kind != TypeUnknown {
84					tc.addError(fmt.Sprintf("if condition must be bool, got %v", condType), n.Line, n.Col)
85				}
86			}
87			if len(n.Children) > 1 {
88				tc.checkNode(n.Children[1])
89			}
90			// Check else branch if present
91			if len(n.Children) > 2 {
92				tc.checkNode(n.Children[2])
93			}
94			return UnitType
95	
96		case ast.NodeReturn:
97			if len(n.Children) > 0 {
98				return tc.checkNode(n.Children[0])
99			}
100			return UnitType
101	
102		case ast.NodeBinaryExpr:
103			return tc.checkBinaryExpr(n)
104	
105		case ast.NodeFieldAccess:
106			return tc.checkFieldAccess(n)
107	
108		case ast.NodeCallExpr:
109			return tc.checkCallExpr(n)
110	
111		case ast.NodeIdent:
112			if t, found := tc.env.Lookup(n.Value); found {
113				return t
114			}
115			tc.addError(fmt.Sprintf("unknown variable '%s'", n.Value), n.Line, n.Col)
116			return UnknownType
117	
118		case ast.NodeIntLit:
119			return IntType
120	
121		case ast.NodeBoolLit:
122			return BoolType
123	
124		case ast.NodeStringLit:
125			return StringType
126	
127		case ast.NodeStructLit:
128			return tc.checkStructLit(n)
129	
130		case ast.NodeForStmt:
131			// Register iterator variable as int (simplified)
132			if len(n.Children) > 0 && n.Children[0].Kind == ast.NodeIdent {
133				tc.env.Define(n.Children[0].Value, IntType)
134			}
135			if len(n.Children) > 2 {
136				tc.checkNode(n.Children[2]) // body
137			}
138			return UnitType
139	
140		default:
141			return UnknownType
142		}
143	}
144	
145	// checkStructDecl registers a struct definition
146	func (tc *TypeChecker) checkStructDecl(n *ast.Node) TypeInfo {
147		structName := n.Value
148		def := StructDef{
149			Name:   structName,
150			Fields: make(map[string]TypeInfo),
151		}
152	
153		// Extract field types from children
154		for _, child := range n.Children {
155			if child.Kind == ast.NodeFieldDecl {
156				fieldName := child.Value
157				// Field type is in TypeAnnotation or Children[0].Value
158				fieldType := UnknownType
159				if child.TypeAnnotation != "" {
160					fieldType = TypeFromAnnotation(child.TypeAnnotation)
161				} else if len(child.Children) > 0 {
162					// Type is in Children[0].Value
163					fieldType = TypeFromAnnotation(child.Children[0].Value)
164				}
165				def.Fields[fieldName] = fieldType
166			}
167		}
168	
169		tc.env.RegisterStruct(structName, def)
170		return UnitType
171	}
172	
173	// checkLetDecl validates variable declaration and registration
174	func (tc *TypeChecker) checkLetDecl(n *ast.Node) TypeInfo {
175		if len(n.Children) < 2 {
176			return UnknownType
177		}
178	
179		nameNode := n.Children[0]
180		valueNode := n.Children[1]
181	
182		// Determine the type of the variable
183		var varType TypeInfo
184	
185		// If there's a type annotation, use it
186		if nameNode.TypeAnnotation != "" {
187			varType = TypeFromAnnotation(nameNode.TypeAnnotation)
188			// Check value type matches declared type
189			inferredType := tc.inferType(valueNode)
190			if inferredType.Kind != TypeUnknown && !varType.Equals(inferredType) {
191				tc.addError(
192					fmt.Sprintf("type mismatch: expected %v, got %v", varType, inferredType),
193					n.Line, n.Col,
194				)
195			}
196		} else {
197			// No annotation: infer from the value expression
198			varType = tc.inferType(valueNode)
199		}
200	
201		// Register the variable
202		tc.env.Define(nameNode.Value, varType)
203		return UnitType
204	}
205	
206	// checkFnDecl validates function declaration and registers function signature
207	func (tc *TypeChecker) checkFnDecl(n *ast.Node) TypeInfo {
208		fnName := n.Value
209	
210		// Collect parameter types
211		paramTypes := []TypeInfo{}
212		tc.env.EnterScope()
213	
214		for _, child := range n.Children {
215			if child.Kind == ast.NodeIdent {
216				// This is a parameter
217				paramType := UnknownType
218				if child.TypeAnnotation != "" {
219					paramType = TypeFromAnnotation(child.TypeAnnotation)
220				}
221				paramTypes = append(paramTypes, paramType)
222				tc.env.Define(child.Value, paramType)
223			}
224		}
225	
226		// Get return type from fn node's TypeAnnotation
227		returnType := UnitType
228		if n.TypeAnnotation != "" {
229			returnType = TypeFromAnnotation(n.TypeAnnotation)
230		}
231	
232		// Check function body
233		for _, child := range n.Children {
234			if child.Kind == ast.NodeBlockStmt {
235				tc.checkNode(child)
236				break
237			}
238		}
239	
240		tc.env.ExitScope()
241	
242		// Register function signature
243		fnDef := FuncDef{
244			Name:       fnName,
245			ParamTypes: paramTypes,
246			ReturnType: returnType,
247		}
248		tc.env.RegisterFunc(fnName, fnDef)
249	
250		return UnitType
251	}
252	
253	// checkBinaryExpr validates binary expression type correctness
254	func (tc *TypeChecker) checkBinaryExpr(n *ast.Node) TypeInfo {
255		if len(n.Children) < 2 {
256			return UnknownType
257		}
258	
259		leftType := tc.checkNode(n.Children[0])
260		rightType := tc.checkNode(n.Children[1])
261	
262		// For now, both operands must be int for arithmetic
263		op := n.Value
264		if op == "+" || op == "-" || op == "*" || op == "/" {
265			if leftType.Kind != TypeInt && leftType.Kind != TypeUnknown {
266				tc.addError(
267					fmt.Sprintf("left operand of %s must be int, got %v", op, leftType),
268					n.Line, n.Col,
269				)
270			}
271			if rightType.Kind != TypeInt && rightType.Kind != TypeUnknown {
272				tc.addError(
273					fmt.Sprintf("right operand of %s must be int, got %v", op, rightType),
274					n.Line, n.Col,
275				)
276			}
277			return IntType
278		}
279	
280		// Comparison operators return bool
281		if op == "==" || op == "!=" || op == "<" || op == ">" || op == "<=" || op == ">=" {
282			if !leftType.Equals(rightType) && leftType.Kind != TypeUnknown && rightType.Kind != TypeUnknown {
283				tc.addError(
284					fmt.Sprintf("type mismatch in %s: %v vs %v", op, leftType, rightType),
285					n.Line, n.Col,
286				)
287			}
288			return BoolType
289		}
290	
291		return UnknownType
292	}
293	
294	// checkFieldAccess validates field access and returns field type
295	func (tc *TypeChecker) checkFieldAccess(n *ast.Node) TypeInfo {
296		if len(n.Children) == 0 {
297			return UnknownType
298		}
299	
300		// Get the object type
301		objType := tc.checkNode(n.Children[0])
302		fieldName := n.Value
303	
304		// Look up struct definition
305		if objType.Kind == TypeStruct {
306			if structDef, found := tc.env.LookupStruct(objType.StructName); found {
307				if fieldType, fieldExists := structDef.Fields[fieldName]; fieldExists {
308					return fieldType
309				}
310				tc.addError(
311					fmt.Sprintf("unknown field '%s' on struct '%s'", fieldName, objType.StructName),
312					n.Line, n.Col,
313				)
314				return UnknownType
315			}
316			tc.addError(fmt.Sprintf("unknown struct '%s'", objType.StructName), n.Line, n.Col)
317			return UnknownType
318		}
319	
320		// Object is not a struct
321		if objType.Kind != TypeUnknown {
322			tc.addError(
323				fmt.Sprintf("cannot access field '%s' on non-struct type %v", fieldName, objType),
324				n.Line, n.Col,
325			)
326		}
327		return UnknownType
328	}
329	
330	// checkCallExpr validates function call and returns return type
331	func (tc *TypeChecker) checkCallExpr(n *ast.Node) TypeInfo {
332		fnName := n.Value
333	
334		// Check for user-defined function
335		if fnDef, found := tc.env.LookupFunc(fnName); found {
336			// Validate argument count
337			if len(n.Children) != len(fnDef.ParamTypes) {
338				tc.addError(
339					fmt.Sprintf("function '%s' expects %d arguments, got %d", fnName, len(fnDef.ParamTypes), len(n.Children)),
340					n.Line, n.Col,
341				)
342			}
343			// Return the function's return type
344			return fnDef.ReturnType
345		}
346	
347		// Check for built-in functions
348		switch fnName {
349		case "print":
350			return UnitType
351		case "len":
352			return IntType
353		case "str":
354			return StringType
355		case "syscall":
356			return IntType
357		default:
358			tc.addError(fmt.Sprintf("unknown function '%s'", fnName), n.Line, n.Col)
359			return UnknownType
360		}
361	}
362	
363	// inferType infers the type of a node without modifying the environment
364	func (tc *TypeChecker) inferType(n *ast.Node) TypeInfo {
365		if n == nil {
366			return UnknownType
367		}
368	
369		switch n.Kind {
370		case ast.NodeIntLit:
371			return IntType
372		case ast.NodeBoolLit:
373			return BoolType
374		case ast.NodeStringLit:
375			return StringType
376		case ast.NodeStructLit:
377			// Infer struct type from the struct name
378			return StructType(n.Value)
379		case ast.NodeIdent:
380			// Look up variable type
381			if t, found := tc.env.Lookup(n.Value); found {
382				return t
383			}
384			return UnknownType
385		case ast.NodeBinaryExpr:
386			return tc.checkBinaryExpr(n)
387		case ast.NodeFieldAccess:
388			return tc.checkFieldAccess(n)
389		case ast.NodeCallExpr:
390			return tc.checkCallExpr(n)
391		default:
392			return UnknownType
393		}
394	}
395	
396	// checkStructLit validates struct initialization
397	func (tc *TypeChecker) checkStructLit(n *ast.Node) TypeInfo {
398		structName := n.Value
399	
400		// Look up struct definition
401		if structDef, found := tc.env.LookupStruct(structName); found {
402			// Validate field initializations
403			for _, child := range n.Children {
404				if child.Kind == ast.NodeFieldDecl {
405					fieldName := child.Value
406					if _, fieldExists := structDef.Fields[fieldName]; !fieldExists {
407						tc.addError(
408							fmt.Sprintf("unknown field '%s' in struct '%s'", fieldName, structName),
409							child.Line, child.Col,
410						)
411					}
412					// Check field value type if we have field type info
413					if len(child.Children) > 0 {
414						fieldValueType := tc.inferType(child.Children[0])
415						expectedType := structDef.Fields[fieldName]
416						if fieldValueType.Kind != TypeUnknown && expectedType.Kind != TypeUnknown && !fieldValueType.Equals(expectedType) {
417							tc.addError(
418								fmt.Sprintf("field '%s' type mismatch: expected %v, got %v", fieldName, expectedType, fieldValueType),
419								child.Line, child.Col,
420							)
421						}
422					}
423				}
424			}
425			return StructType(structName)
426		}
427	
428		// Struct not found
429		tc.addError(fmt.Sprintf("unknown struct '%s'", structName), n.Line, n.Col)
430		return UnknownType
431	}
432	
433	// addError records a type error
434	func (tc *TypeChecker) addError(msg string, line, col int) {
435		tc.errors = append(tc.errors, TypeError{
436			Message: msg,
437			Line:    line,
438			Col:     col,
439		})
440	}
