388	// genCallExpr generates IR for a function call
389	func (g *Generator) genCallExpr(node *ast.Node) (Operand, error) {
390		if len(node.Children) == 0 {
391			return Operand{}, fmt.Errorf("call expression requires function name")
392		}
393	
394		fnName := node.Children[0].Value
395	
396		// Special handling for syscall
397		if fnName == "syscall" {
398			if len(node.Children) < 2 {
399				return Operand{}, fmt.Errorf("syscall requires at least syscall number")
400			}
401	
402			// syscall number (always first arg after function name)
403			numOp, err := g.genExpr(node.Children[1])
404			if err != nil {
405				return Operand{}, err
406			}
407	
408			// Additional args (starting from index 2)
409			for i := 2; i < len(node.Children); i++ {
410				argOp, err := g.genExpr(node.Children[i])
411				if err != nil {
412					return Operand{}, err
413				}
414				g.emit(Instruction{
415					Op:   OpParam,
416					Src1: argOp,
417				})
418			}
419	
420			// Emit syscall instruction
421			result := g.newTemp()
422			g.emit(Instruction{
423				Op:   OpSyscall,
424				Dest: result,
425				Src1: numOp,
426			})
427	
428			return result, nil
429		}
430	
431		// Emit parameters for regular function calls
432		for i := 1; i < len(node.Children); i++ {
433			argOp, err := g.genExpr(node.Children[i])
434			if err != nil {
435				return Operand{}, err
436			}
437			g.emit(Instruction{
438				Op:   OpParam,
439				Src1: argOp,
440			})
441		}
442	
443		// Emit call
444		result := g.newTemp()
445		g.emit(Instruction{
446			Op:   OpCall,
447			Dest: result,
448			Fn:   fnName,
449		})
450	
451		return result, nil
452	}
